	// clear the goal before the new state is set
	m_goalObjectID = (ObjectID)0;
	m_goalPosition.x = 0.0f;
	m_goalPosition.y = 0.0f;
	m_goalPosition.z = 0.0f;
	m_secondGoalObjectID = (ObjectID)0;
	m_goalRange = FLT_MAX;

